class FeatureFlags:
    def __init__(self):
        self._flags = {
            "search": False,
            "export": False
        }
        self._checkpoints = []

    def set(self, name, enabled):
        if name not in self._flags:
            raise ValueError(f"Unknown feature flag: {name}")
        self._flags[name] = bool(enabled)

    def get(self, name):
        return self._flags.get(name, False)

    def checkpoint(self):
        self._checkpoints.append(dict(self._flags))

    def rollback(self, checkpoint_index=-1):
        if not self._checkpoints:
            raise ValueError("No checkpoints available to roll back to.")
        if checkpoint_index < -len(self._checkpoints) or checkpoint_index >= len(self._checkpoints):
            raise IndexError("Checkpoint index out of range.")
        self._flags = self._checkpoints[checkpoint_index]
        self._checkpoints = self._checkpoints[:checkpoint_index]
```

